def predict(x, m, b):
    return m * x + b

print(predict(3, 0.5, 2))  # 3.5

points = [(1, 2), (2, 3), (3, 5), (4, 4)]

def total(m, b):
    return sum((y - (m * x + b)) ** 2 for x, y in points)

print(round(total(0.5, 2), 2), round(total(1, 1), 2), round(total(0.8, 1.5), 2))

points = [(1, 2), (2, 3), (3, 5), (4, 4)]

def total(m, b):
    return sum((y - (m * x + b)) ** 2 for x, y in points)

candidates = [(0.5, 2), (1, 1), (0.8, 1.5)]
print(min(candidates, key=lambda c: total(*c)))  # (0.8, 1.5)
